// Extract user query and user_id from input
const query = $input.item.json.query;
const userId = $input.item.json.user_id;
const conversationId = $input.item.json.conversation_id;

return {
  query,
  userId,
  conversationId,
  timestamp: new Date().toISOString()
};

// Parse user history and current query embedding
const history = JSON.parse($input.first().json.history || '[]');
const currentEmbedding = $input.last().json.embedding;
const currentQuery = $input.last().json.query;

// Calculate cosine similarity with previous queries
function cosineSimilarity(a, b) {
  const dotProduct = a.reduce((sum, val, i) => sum + val * b[i], 0);
  const magA = Math.sqrt(a.reduce((sum, val) => sum + val * val, 0));
  const magB = Math.sqrt(b.reduce((sum, val) => sum + val * val, 0));
  return dotProduct / (magA * magB);
}

let bestMatch = null;
let highestSimilarity = 0;

for (const historyItem of history) {
  if (historyItem.embedding && historyItem.embedding.length === currentEmbedding.length) {
    const similarity = cosineSimilarity(currentEmbedding, historyItem.embedding);

    if (similarity >= 0.85 && similarity > highestSimilarity) {
      highestSimilarity = similarity;
      bestMatch = {
        query: historyItem.query,
        timestamp: historyItem.timestamp,
        result_id: historyItem.result_id,
        similarity: similarity
      };
    }
  }
}

return {
  hasSimilarQuery: bestMatch !== null,
  similarQuery: bestMatch,
  currentQuery: currentQuery,
  currentEmbedding: currentEmbedding
};

// Format similar query suggestion using template
const templates = $input.first().json;
const similarQuery = $input.last().json.similarQuery;

const template = templates.suggestions.similar_query;
const suggestion = template
  .replace('{{date}}', new Date(similarQuery.timestamp).toLocaleDateString())
  .replace('{{previous_query}}', similarQuery.query);

return {
  suggestion,
  similarity: similarQuery.similarity,
  result_id: similarQuery.result_id
};

// Store new query with embedding in user history
const userId = $input.item.json.userId;
const query = $input.item.json.currentQuery;
const embedding = $input.item.json.currentEmbedding;
const timestamp = new Date().toISOString();

// Get existing history
const existingHistory = JSON.parse($input.item.json.existingHistory || '[]');

// Add new query
const newEntry = {
  query,
  embedding,
  timestamp,
  result_id: null  // Will be updated when result is available
};

existingHistory.push(newEntry);

// Keep only last 50 queries
const trimmedHistory = existingHistory.slice(-50);

return {
  key: `user:${userId}:history`,
  value: JSON.stringify(trimmedHistory),
  ttl: 604800  // 7 days
};

// Return final response
const hasSuggestion = $input.item.json.suggestion !== undefined;

if (hasSuggestion) {
  return {
    hasSimilarQuery: true,
    suggestion: $input.item.json.suggestion,
    similarity: $input.item.json.similarity,
    result_id: $input.item.json.result_id
  };
} else {
  return {
    hasSimilarQuery: false,
    suggestion: null
  };
}
